INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62147344', 62147344, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA PELABUHAN MAMUJU', 'PENYELENGGARAAN ANGKUTAN LAUT PERINTIS R-44', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Barat, Mamuju (Kab.)', 8113471000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Trayek', '1) perusahaan pelayaran nasional swasta mengoperasikan trayek perintis untuk Pangkalan Mamuju Rute R-44, keseluruhan trayek tersebut adalah untuk melayani jaringan trayek angkutan laut dalam negeri yang teratur dan berjadwal tetap (liner) yang telah ditetapkan, memenuhi standar pelayanan (SP) dalam pemberian pelayanan kapal perintis dan menjamin kelangsungan pelayanan secara berkesinambungan; 2) melaksanakan pelayaran angkutan laut perintis berdasarkan trayek angkutan laut perintis yang telah ditetapkan oleh Direktur Jenderal Perhubungan Laut dengan menggunakan tarif yang ditetapkan oleh Menteri; 3) perusahaan pelayaran wajib menggunakan kapal perintis milik negara; 4) menempatkan (manning) Nahkoda dan anak buah kapal sesuai dengan persyaratan Standard Training Certification Watch Keeping Of Seafarers (STCW) 1978 amandemen 2010; 5) melaksanakan (implementasi) Manajemen Keselamatan Kapal atau Internasional Safety Management (ISM) Code; 6) menjaga keselamatan dan keamanan penumpang dan barang; 7) menyediakan kapal pengganti selama kapal utama dalam masa perawatan tahunan (annual docking) atau mengalami kerusakan; 8) melakukan perawatan kapal harian dan perawatan tahunan terhadap kapal utama; 9) Memiliki aplikasi e-Tiketing untuk penumpang dan barang yang dapat terintegrasi dengan sistem monitoring manifest kapal di Direktorat Lalu Lintas dan Angkutan Laut. 10) melaksanakan dan mematuhi kontrak yang ditandatangani oleh Pejabat Pembuat Komitmen (PPK) dengan pelaksana penyelenggaraan kegiatan pelayanan publik kapal perintis; 11) membuat dan menyampaikan laporan tertulis serta dokumentasi berupa audio visual penyelenggaraan untuk kegiatan pelayanan publik kapal perintis pada setiap pelabuhan pangkalan dan singgah', '1) perusahaan pelayaran nasional swasta mengoperasikan trayek perintis untuk Pangkalan Mamuju Rute R-44, keseluruhan trayek tersebut adalah untuk melayani jaringan trayek angkutan laut dalam negeri yang teratur dan berjadwal tetap (liner) yang telah ditetapkan, memenuhi standar pelayanan (SP) dalam pemberian pelayanan kapal perintis dan menjamin kelangsungan pelayanan secara berkesinambungan; 2) melaksanakan pelayaran angkutan laut perintis berdasarkan trayek angkutan laut perintis yang telah ditetapkan oleh Direktur Jenderal Perhubungan Laut dengan menggunakan tarif yang ditetapkan oleh Menteri; 3) perusahaan pelayaran wajib menggunakan kapal perintis milik negara; 4) menempatkan (manning) Nahkoda dan anak buah kapal sesuai dengan persyaratan Standard Training Certification Watch Keeping Of Seafarers (STCW) 1978 amandemen 2010; 5) melaksanakan (implementasi) Manajemen Keselamatan Kapal atau Internasional Safety Management (ISM) Code; 6) menjaga keselamatan dan keamanan penumpang dan barang; 7) menyediakan kapal pengganti selama kapal utama dalam masa perawatan tahunan (annual docking) atau mengalami kerusakan; 8) melakukan perawatan kapal harian dan perawatan tahunan terhadap kapal utama; 9) Memiliki aplikasi e-Tiketing untuk penumpang dan barang yang dapat terintegrasi dengan sistem monitoring manifest kapal di Direktorat Lalu Lintas dan Angkutan Laut. 10) melaksanakan dan mematuhi kontrak yang ditandatangani oleh Pejabat Pembuat Komitmen (PPK) dengan pelaksana penyelenggaraan kegiatan pelayanan publik kapal perintis; 11) membuat dan menyampaikan laporan tertulis serta dokumentasi berupa audio visual penyelenggaraan untuk kegiatan pelayanan publik kapal perintis pada setiap pelabuhan pangkalan dan singgah', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 260805);
