INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62145627', 62145627, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Pembangunan ZI menuju WBK, Penguatan  pendampingan assesment penilaain Satker WBK /WBBM Zona Integritas menuju satker WBK, Penguatan dan pendampingan assesment Penilaian Satker', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 2844000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Belanja Bahan;', 'Pekerjaan ini meliputi penyediaan sarana pendukung administrasi, media informasi, dan logistik kegiatan yang diperlukan untuk menunjang rangkaian proses pembangunan Zona Integritas (ZI) menuju wilayah bebas dari korupsi (WBK) dan wilayah birokrasi bersih melayani (WBBM) di lingkungan Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan bahan pendukung pendampingan asesmen seperti ATK khusus penggandaan dokumen bukti dukung (evidence), pembuatan media sosialisasi (seperti banner, spanduk, atau stiker layanan) sebagai bentuk penguatan kampanye publik, serta dukungan logistik untuk pelaksanaan rapat-rapat koordinasi tim penilai internal maupun eksternal. Spesifikasi bahan ditekankan pada kualitas fungsional yang memadai untuk memastikan seluruh data dukung penilaian dapat terorganisir dengan rapi dan pesan perubahan layanan dapat tersampaikan secara jelas kepada masyarakat. Pengadaan ini bertujuan untuk menjamin kelancaran tahapan penilaian mandiri, verifikasi lapangan, hingga evaluasi akhir, guna memenuhi target kinerja instansi dalam mewujudkan tata kelola pemerintahan yang bersih, transparan, dan akuntabel sepanjang tahun anggaran 2026', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 261115);
