INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62144252', 62144252, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Pakaian Dinas Lapangan', 'Barang', 'E-Purchasing', 'Kepulauan Riau, Tanjung Pinang (Kota)', 39250000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '(1, PT, @ 39250000 )', '1. Pakaian Dinas Lapangan ( 1, PT, @ 39250000 );', 'Pekerjaan ini meliputi pengadaan Pakaian Dinas Lapangan (PDL) yang terdiri dari kemeja dan celana panjang untuk mendukung operasional pegawai di lapangan. Spesifikasi teknis utama menggunakan bahan kain jenis Ripstop atau Drill berkualitas tinggi yang memiliki karakteristik kuat, tahan lama, tidak mudah pudar, dan nyaman digunakan untuk aktivitas luar ruangan (outdoor). Desain pakaian harus mengikuti standar seragam instansi yang berlaku, lengkap dengan atribut bordir komputer berupa nama personel, logo instansi, serta label jabatan yang rapi dan presisi. Proses pengerjaan mencakup pengambilan data ukuran masing-masing personel (custom size) guna memastikan kenyamanan pemakaian, dengan kualitas jahitan ganda (rangkap) yang kuat dan finishing yang bersih sesuai dengan standar pakaian dinas pemerintah', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 261393);
