INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62146084', 62146084, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Bahan Pengendalian Vektor (Insektisida)', 'Barang', 'E-Purchasing', 'Kepulauan Riau, Tanjung Pinang (Kota)', 15230000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '( 1, PT, @ 15230000 )', '1. Bahan Pengendalian Vektor (Insektisida) ( 1, PT, @ 15230000 );', 'Pekerjaan ini meliputi penyediaan bahan kimia pengendalian vektor (insektisida) yang akan digunakan untuk memutus rantai penularan penyakit bersumber binatang seperti DBD, Malaria, dan Filariasis di wilayah kerja Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan insektisida cair atau bubuk yang efektif untuk kegiatan pengasapan (fogging), pengkabutan (cold fogging/ULV), maupun penyemprotan dinding (IRS). Spesifikasi teknis mewajibkan bahan yang disediakan memiliki izin edar resmi dari kementerian terkait guna menjamin keamanan bagi petugas dan ramah terhadap lingkungan. Pengadaan ini bertujuan untuk memastikan ketersediaan stok bahan intervensi yang berkualitas tinggi dan siap pakai, sehingga upaya pengendalian populasi vektor dapat dilakukan secara cepat dan tepat sasaran dalam mencegah terjadinya kejadian luar biasa (KLB) sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 261512);
