INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62147860', 62147860, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Dokumen Teknis Gedung Pemda - SAPS 14 (MEP) 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Lingkup kegiatan yang dilakukan oleh penyedia jasa Senior Assistant Professional Staff (SAPS) 14 - MEP, meliputi: a. Membantu pemeriksaan kelengkapan standar teknis bangunan gedung bidang LAK (Instalasi Arus Kuat) dan LAL (Instalasi Arus lemah) serta penerbitan surat pernyataan pemenuhan standar teknis dalam rangka Persetujuan Bangunan Gedung dan Sertifikat Laik Fungsi (SLF) bangunan Gedung; b. Membantu penyusunan perencanaan teknis pembangunan, perawatan dan pemeliharaan bangunan gedung pemerintah daerah bidang LAK (Instalasi Arus Kuat) dan LAL (Instalasi Arus lemah), serta c. Membantu memeriksa dan mengkaji kembali (review) dokumen perencanaan bidang LAK (Instalasi Arus Kuat) dan LAL (Instalasi Arus lemah) yang dibuat oleh jasa konsultan perencana maupun yang dibuat oleh Seksi Pembinaan Gedung Pemda (in house). d. Membantu pendampingan pengawasan pelaksanaan perawatan, pemeliharaan dan pembangunan SKPD/UKPD untuk LAK (Instalasi Arus Kuat) dan LAL (Instalasi Arus lemah). "', '"Senior Assistant Profesional Staff bidang MEP dengan ketentuan sebagai berikut : a. Pendidikan Minimal S1/D4/Setara Jurusan Teknik Elektro dari Universitas Negeri/ Swasta dengan status lain yang telah mengikuti ujian negara atau lulusan luar negeri bagi penyedia jasa Senior Assistant Professional Staff; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan yang dibuktikan dengan ijazah dan transkrip nilai pendidikan terakhir Jurusan Teknik Elektro, sertifikat keahlian/teknis seperti AutoCAD, Microsoft Office dan/atau sertifikat pelatihan/kursus; dan c. Pengalaman Kerja minimal 1 tahun di bidang perencanaan, pembangunan, perawatan bangunan gedung dan/atau pekerjaan sejenis. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 261872);
