INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62146760', 62146760, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Perlengkapan Pelayanan Asrama/Kelas', 'Barang', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 225423000, 'July 2026', 'APBN - PNBP (D)', 1, 1, '1 PT', 'Pengadaan perlengkapan pelayanan asrama dan/atau kelas dengan ruang lingkup pekerjaan sebagai berikut: 1. Penyediaan Perlengkapan - Menyediakan perlengkapan asrama/kelas sesuai daftar kebutuhan yang ditetapkan. - Menjamin seluruh barang dalam kondisi baru, layak pakai, dan aman digunakan. 2. Pengadaan dan Pengemasan - Mengadakan barang sesuai spesifikasi teknis. - Mengemas barang dengan rapi dan aman untuk pengiriman. 3. Distribusi dan Pengiriman - Mengirimkan perlengkapan ke lokasi asrama dan/atau kelas sesuai jadwal. - Menjamin ketepatan jumlah, jenis, dan kondisi barang yang dikirim. 4. Pemeriksaan dan Serah Terima - Melakukan pemeriksaan bersama terhadap jumlah, kualitas, dan kesesuaian barang. - Menyerahkan barang dalam kondisi siap digunakan. 5. Pengendalian Mutu - Bertanggung jawab mengganti barang yang rusak, cacat, atau tidak sesuai spesifikasi.', '1. Perlengkapan Asrama Contoh: - Bantal dan guling - Seprai dan selimut - Tempat sampah - Ember dan gayung - Jemuran pakaian - dll 2. Perlengkapan Kelas Contoh: - Jam dinding - Tempat sampah kelas 3. Spesifikasi Umum Barang - Bahan: Kayu / besi / plastik berkualitas - Konstruksi: Kokoh dan aman digunakan - Finishing: Rapi dan tidak membahayakan pengguna 4. Standar Mutu - Barang baru dan bukan bekas. - Bebas dari cacat produksi. - Sesuai standar keselamatan dan kenyamanan. 5. Jumlah dan Jenis - Disesuaikan dengan kapasitas asrama dan kelas. - Ditetapkan dalam daftar rinci kebutuhan (RAB). 6. Waktu Pelaksanaan - Waktu pengadaan dan pengiriman: Sesuai jadwal yang ditentukan panitia/kegiatan. Ketentuan Tambahan - Harga sudah termasuk pengemasan dan pengiriman, dan pajak - Penyedia wajib memberikan garansi terbatas (jika ada). - Barang yang tidak sesuai spesifikasi wajib diganti.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 262392);
