INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62185929', 62185929, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA KABUPATEN MADIUN 04', 'Biaya Jasa Layanan Pos Bantuan Hukum 1 Jam Layanan', 'Jasa Konsultansi', 'E-Purchasing', 'Jawa Timur, Madiun (Kab.)', 70000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 700, Orang, @ 100000 )', '1. Biaya Jasa Layanan Pos Bantuan Hukum 700 orang/jam Layanan ( 700, Orang, @ Rp. 100.000,- );', 'Persyaratan Utama (Individu & Badan Usaha): 1. Izin Praktik Advokat: Advokat pendiri harus memiliki Izin Praktik yang dikeluarkan organisasi profesi advokat yang diakui oleh Negara Kesatuan Republik Indonesia dan setelah lulus PKPA, Ujian Profesi, Magang, dan disumpah oleh Pengadilan Tinggi. 2. Akta Pendirian: Akta Pendirian Badan Usaha (Firma, PT, CV, Persekutuan Perdata) yang dibuat oleh Notaris. 3. Pengesahan Kemenkumham: Akta pendirian harus disahkan oleh Kementerian Hukum dan HAM (AHU). 4. Nomor Induk Berusaha (NIB): Diperoleh melalui sistem Online Single Submission (OSS). 5. NPWP Badan: Nomor Pokok Wajib Pajak untuk badan usaha dan Laporan SPT 3 tahun terakhir. 6. Surat Keterangan Domisili Perusahaan (SKDP): Surat keterangan alamat usaha dari kelurahan/kecamatan. 7. memiliki Sertifikasi Standar Pos Bantuan Hukum dari Kementerian Hukum RI. 8. memilik akun untuk pengadaan jasa konsultansi secara elektronik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 262927);
