INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62146193', 62146193, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Sewa Kendaraan PKL Pelatihan Entomolog Malaria (PNBP)', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Selatan, Makassar (Kota)', 11900000, 'July 2026', 'APBN - PNBP (D)', 1, 1, '10 OK', 'Penyediaan kendaraan operasional untuk mendukung pelaksanaan kegiatan PKL/Pelatihan, dengan ruang lingkup pekerjaan sebagai berikut: 1. Penyediaan Kendaraan - Menyediakan kendaraan sesuai jenis dan jumlah yang ditetapkan panitia. - Kendaraan digunakan untuk transportasi peserta, fasilitator, dan/atau panitia selama kegiatan PKL/Pelatihan. 2. Pengemudi - Menyediakan pengemudi yang berpengalaman, memiliki SIM yang masih berlaku, dan memahami rute perjalanan. - Pengemudi wajib mematuhi peraturan lalu lintas dan standar keselamatan. 3. Operasional Kendaraan - Kendaraan siap digunakan sesuai jadwal kegiatan. - Menjamin ketepatan waktu penjemputan dan pengantaran. 4. Pemeliharaan dan Keamanan - Menjamin kendaraan dalam kondisi laik jalan, bersih, dan aman. - Bertanggung jawab atas perawatan rutin kendaraan selama masa sewa. 5. Asuransi dan Keselamatan - Kendaraan dilengkapi asuransi kendaraan dan/atau penumpang sesuai ketentuan. - Menyediakan perlengkapan keselamatan standar. 6. Penggantian Kendaraan - Menyediakan kendaraan pengganti dengan spesifikasi setara apabila terjadi kerusakan selama masa sewa tanpa biaya tambahan.', '1. Jenis Kendaraan Disesuaikan dengan kebutuhan kegiatan, antara lain: Minibus (contoh: Hiace / Elf) atau Mobil operasional (MPV/SUV dan lainnya) 2. Kapasitas Minibus: ± 12–15 orang, atau menyesuaikan 3. Kondisi Kendaraan - Tahun kendaraan maksimal 5–7 tahun terakhir - Kondisi mesin prima dan laik jalan - Interior bersih dan nyaman - AC berfungsi dengan baik 4. Fasilitas Minimal - AC - Sabuk pengaman - Kursi penumpang nyaman - Bagasi memadai 5. Pengemudi - Memiliki SIM sesuai jenis kendaraan - Berpengalaman minimal 2 tahun - Berpenampilan rapi dan sopan - Sehat jasmani dan rohani 6. Durasi dan Pola Sewa - Durasi sewa: Harian selama masa PKL/Pelatihan - Jam operasional : disesuaikan dengan jadwal PKL pelatihan - Rute: disesuaikan dengan lokasi PKL/Pelatihan Ketentuan Tambahan Harga sewa sudah termasuk: - Kendaraan - Pengemudi - BBM - Biaya parkir dan tol (jika terdapat)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 263712);
