INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62146759', 62146759, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pencetakan Bahan Promosi dan Publikasi', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 56012000, 'July 2026', 'APBN - PNBP (D)', 1, 1, '1 PT', 'Pencetakan bahan promosi dan publikasi untuk mendukung kegiatan informasi, sosialisasi, dan branding instansi', '1. Jenis Bahan Cetak - Spanduk / Banner - Poster - Brosur / Flyer - Leaflet - Booklet - X-Banner / Roll Banner - Baliho dll 2. Spesifikasi Umum - Cetak: Full color - Resolusi: Minimal 300 dpi (untuk hasil optimal) - Desain: Memuat logo, nama kegiatan, dan informasi penting 3. Jumlah Cetak Disesuaikan dengan kebutuhan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 263928);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62146761', 62146761, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Layar Interaktif', 'Barang', 'E-Purchasing', 'Sulawesi Selatan, Makassar (Kota)', 288000000, 'October 2026', 'APBN - PNBP (D)', 1, 1, '2 UNIT', 'Pengadaan Layar Interaktif (Interactive Flat Panel/IFP) untuk mendukung proses pembelajaran, pelatihan, dan presentasi interaktif, dengan ruang lingkup pekerjaan sebagai berikut: 1. Penyediaan Perangkat - Menyediakan layar interaktif sesuai spesifikasi teknis yang ditetapkan. - Menjamin perangkat dalam kondisi baru dan bergaransi resmi. 2. Pengiriman dan Instalasi - Mengirimkan layar interaktif ke lokasi yang ditentukan. - Melakukan pemasangan dan instalasi perangkat (bracket/standing). 3. Konfigurasi dan Pengujian - Melakukan konfigurasi awal sistem. - Menguji fungsi layar sentuh, tampilan, suara, dan konektivitas. 4. Pelatihan Singkat Penggunaan - Memberikan penjelasan singkat kepada pengguna mengenai pengoperasian dasar layar interaktif. 5. Serah Terima dan Dokumentasi - Melakukan serah terima perangkat dalam kondisi siap pakai. - Menyerahkan dokumen pendukung (manual, kartu garansi).', '1. Ukuran Layar 86” (disesuaikan kebutuhan ruang) 2. Resolusi dan Tampilan - Resolusi minimal: 4K UHD (3840 x 2160) - Tingkat kecerahan: Minimal 350 cd/m² - Kontras: Minimal 1200:1 - Viewing angle: 178° 3. Teknologi Sentuh - Teknologi: Infrared Touch / Capacitive Touch - Jumlah titik sentuh: Minimal 20 titik sentuh - Respon sentuh: ≤ 10 ms - Mendukung multi-user touch 4. Sistem Operasi - OS bawaan: Android (minimal versi terbaru yang stabil) - Slot OPS PC: Mendukung PC Windows (opsional) 5. Performa - RAM minimal: 4 GB - Penyimpanan internal: Minimal 32 GB 6. Audio - Speaker internal: - Minimal 2 x 15 Watt - Output audio eksternal tersedia 7. Konektivitas - Port: HDMI (in/out) USB (Type A dan/atau Type C) LAN Audio out - Konektivitas nirkabel: Wi-Fi Bluetooth 8. Fitur Pendukung - Whiteboard digital - Screen sharing (wireless) - Annotasi langsung di layar - Kompatibel dengan Windows, macOS, Android, dan iOS 9. Daya dan Keamanan - Tegangan: AC 100–240V - Konsumsi daya efisien - Dilengkapi pengaman panas berlebih 10. Aksesori - Bracket dinding / standing floor - Stylus pen (minimal 2 buah) - Remote control - Kabel pendukung 11. Garansi dan Layanan Purna Jual - Garansi resmi minimal 1 tahun - Layanan purna jual dan pusat servis tersedia di Indonesia Ketentuan Tambahan - Perangkat harus memiliki sertifikat TKDN (jika diperlukan). - Harga sudah termasuk pengiriman, instalasi, dan konfigurasi. - Penyedia wajib mengganti unit jika ditemukan cacat produksi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 263929);
