INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62145303', 62145303, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Biaya Pelatihan SAKIP Daring', 'Jasa Lainnya', 'E-Purchasing', 'Kepulauan Riau, Tanjung Pinang (Kota)', 5000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '( 10, PT, @ 500000 )', '1. Biaya Pelatihan SAKIP Daring ( 10, PT, @ 500000 );', 'Pekerjaan ini merupakan pengadaan jasa penyelenggaraan pelatihan atau bimbingan teknis mengenai Sistem Akuntabilitas Kinerja Instansi Pemerintah (SAKIP) yang dilaksanakan secara daring (online). Ruang lingkup pekerjaan mencakup kepesertaan dalam kelas pelatihan yang diselenggarakan oleh lembaga pelatihan terakreditasi, akses ke platform pembelajaran digital, penyediaan materi/modul pelatihan dalam bentuk elektronik, serta pemberian sertifikat pelatihan bagi peserta yang memenuhi syarat. Pelatihan ini secara khusus dirancang untuk meningkatkan pemahaman dan keterampilan pegawai dalam penyusunan perencanaan kinerja, pengukuran kinerja, pelaporan kinerja, hingga evaluasi internal guna meningkatkan nilai akuntabilitas Satuan Kerja. Melalui metode daring, pelaksanaan tetap mengedepankan efektivitas interaksi antara pengajar dan peserta melalui diskusi interaktif dan studi kasus tanpa harus melakukan mobilisasi fisik, sehingga mendukung efisiensi anggaran operasional kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 264134);
