INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62181791', 62181791, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'Belanja Bahan Rapat Monitoring kegiatan SPBUN', 'Barang', 'Pengadaan Langsung', 'Bali, Jembrana (Kab.)', 1980000, 'June 2025', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Snack rapat biasa ( 33, OK, @ 20000 ); 2. makan rapat biasa ( 33, OK, @ 40000 );', 'Berikut adalah rincian spesifikasi pekerjaan untuk pengadaan konsumsi (Snack dan Makan) rapat rutin atau rapat biasa di instansi Kesyahbandaran. Spesifikasi ini disusun berdasarkan standar harga Rp20.000 (Snack) dan Rp40.000 (Makan) per orang/kali (OK). 1. Spesifikasi Snack Rapat Biasa Jumlah: 33 OK | Harga Satuan: Rp20.000 Untuk plafon harga Rp20.000, standarnya adalah penyajian menggunakan kotak (snack box) dengan komposisi sebagai berikut: Variasi Isi: Minimal 3 jenis kue (Kombinasi rasa manis dan asin/gurih). Contoh manis: Risol, Lemper, atau Pastel. Contoh gurih: Bolu, Pie Buah, atau Lapis Legit. Minuman: Air mineral kemasan botol kecil (330ml) atau gelas (240ml). Kemasan: Kotak karton bersih dengan alas tisu dan plastik pembungkus makanan di dalamnya. Waktu Penyajian: Maksimal sudah tiba di lokasi 30 menit sebelum acara dimulai. 2. Spesifikasi Makan Rapat Biasa Jumlah: 33 OK | Harga Satuan: Rp40.000 Untuk harga Rp40.000, penyajian biasanya berbentuk Nasi Kotak (Box) yang lengkap atau Prasmanan sederhana (tergantung kesepakatan vendor). Berikut rincian standarnya: Komposisi Menu (4 Sehat): Karbohidrat: Nasi Putih. Protein Nabati: Tempe/Tahu (Orek, Bacem, atau Goreng). Protein Hewani: Ayam (Bakar/Goreng/Rica) atau Daging/Ikan. Sayuran: Tumis sayuran, Capcay, atau Urap. Pelengkap: Sambal, Kerupuk, dan Buah potong (Pisang/Semangka/Melon). Minuman: Air mineral botol (330ml/600ml). Alat Makan: Sendok dan garpu plastik standar (kokoh) serta tisu. Kualitas: Makanan harus dalam keadaan segar (tidak basi), diolah dengan higienis, dan dikirim dengan kendaraan tertutup.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 264391);
