INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62146083', 62146083, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Penyediaan Formulir Pendukung Kekarantinaan Kesehatan', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 300000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '( 1, PT, @ 300000 )', '1. Penyediaan Formulir Pendukung Kekarantinaan Kesehatan ( 1, PT, @ 300000 );', 'Pekerjaan ini meliputi penyediaan dan penggandaan berbagai formulir standar serta dokumen administrasi teknis yang digunakan dalam pengawasan kekarantinaan kesehatan di pintu masuk negara (pelabuhan/bandara/pos lintas batas). Ruang lingkup pengadaan mencakup pencetakan formulir pemeriksaan alat angkut, kartu kewaspadaan kesehatan, lembar persetujuan tindakan medis, serta formulir laporan hasil pemeriksaan kesehatan penumpang dan kru. Spesifikasi teknis difokuskan pada kualitas cetakan yang jelas, tajam, dan tidak mudah luntur, menggunakan jenis kertas yang sesuai dengan kebutuhan kearsipan agar data tetap terbaca dalam jangka waktu lama. Pengadaan ini bertujuan untuk menjamin ketersediaan dokumen fisik yang memadai bagi petugas lapangan, guna memastikan seluruh proses pelayanan kekarantinaan kesehatan terdokumentasi dengan akurat, sah secara hukum, dan sesuai dengan standar prosedur operasional sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265521);
