INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148587', 62148587, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan Gedung Bertingkat', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Selatan, Makassar (Kota)', 439950000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'Pekerjaan Pemeliharaan Gedung Bertingkat adalah kegiatan untuk menjaga, memperbaiki, dan mempertahankan kondisi bangunan beserta seluruh sistem pendukungnya agar tetap berfungsi secara optimal, aman, dan nyaman digunakan. Pekerjaan ini dilaksanakan secara berkala maupun insidental sesuai kondisi kerusakan. Ruang lingkup pekerjaan meliputi: I. Pemeliharaan Struktur Bangunan - Pemeriksaan dan perbaikan ringan pada elemen struktur (kolom, balok, pelat lantai). - Penutupan retak rambut non-struktural. - Perlindungan elemen struktur dari korosi dan pelapukan. II. Pemeliharaan Arsitektural - Perbaikan dinding, plesteran, dan pengecatan ulang. - Penggantian plafon rusak. - Perbaikan lantai (keramik, granit, vinil). - Perawatan pintu, jendela, dan kaca. III. Pemeliharaan Sistem Mekanikal - Pemeriksaan dan perbaikan sistem air bersih dan air kotor. - Perbaikan pompa air dan tangki penampungan. - Perawatan instalasi sanitasi. IV. Pemeliharaan Sistem Elektrikal - Perbaikan dan penggantian lampu penerangan. - Perbaikan instalasi kabel, saklar, dan stop kontak. - Pemeriksaan panel listrik dan pengaman arus. - Pemeliharaan sistem penerangan darurat. V. Pemeliharaan Sistem Keselamatan Gedung - Pemeriksaan APAR dan hydrant. - Perawatan alarm kebakaran dan jalur evakuasi. - Pemeriksaan rambu keselamatan. VI. Pekerjaan Penunjang - Pembersihan area kerja. - Pengujian fungsi setelah pekerjaan selesai. - Dokumentasi hasil pekerjaan.', '1. Spesifikasi Umum - Pekerjaan dilaksanakan sesuai standar teknis bangunan gedung. - Menggunakan bahan berkualitas baik dan sesuai standar nasional (SNI). - Tenaga kerja harus berpengalaman dan kompeten. - Mengutamakan keselamatan dan kesehatan kerja (K3). - Area kerja pada lantai tinggi wajib menggunakan pengaman kerja. 2. Spesifikasi Teknis per Pekerjaan a. Pekerjaan Arsitektural - Cat dinding: Cat tembok eksterior/interior berbahan acrylic, tahan cuaca. - Plafon: Gypsum atau GRC, rangka hollow galvanis atau kayu disesuaikan dengan kondisi awal. - Lantai: Keramik/granit minimal mutu standar bangunan gedung. - Kaca: Kaca polos/tempered sesuai fungsi. b. Pekerjaan Mekanikal (Plumbing) - Pipa air: PVC/PP-R, kelas AW. - Kran air: Kuningan/stainless steel, ukuran ½ inci. - Pompa air: Daya sesuai kapasitas gedung. - Sanitair: Closet, wastafel standar gedung bertingkat. c. Pekerjaan Elektrikal - Lampu: LED, efisiensi energi, tegangan 220 V. - Kabel: NYM/NYA berstandar SNI. - Panel listrik: Dilengkapi MCB dan sistem pentanahan. - Saklar & stop kontak: Standar SNI. d. Sistem Keselamatan - APAR: Powder/CO₂ sesuai kelas kebakaran. - Hydrant: Indoor/outdoor sesuai standar keselamatan. - Lampu darurat: Baterai otomatis saat listrik padam.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265684);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62908510', 62908510, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM33 KANTOR IMIGRASI KELAS II NON TPI MAMUJU', 'Pengadaan Belanja Barang Non Operasional Lainnya Kegiatan Pengelolaan Informasi dan Komunikasi Keimigrasian Pada Kantor Imigrasi Kelas II Non TPI Mamuju - Sulawesi Barat Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Barat, Mamuju (Kab.)', 117743000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Biaya penyebaran informasi melalui media ( 1, Pkt, @ 82943000 ); 2. Pemeliharaan website ( 1, Thn, @ 30000000 ); 3. Biaya Paket Data ( 1, Thn, @ 4800000 );', 'Mengadakan Belanja Barang Non Operasional Lainnya Berupa Biaya penyebaran informasi melalui media, Pemeliharaan website, Biaya Paket Data, Kegiatan Pengelolaan Informasi dan Komunikasi Keimigrasian Pada Kantor Imigrasi Kelas II Non TPI Mamuju - Sulawesi Barat Tahun Anggaran 2026', 30000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 265685);
