INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148595', 62148595, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan Genset (Kapasitas dibawah 100 KVA)', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 8627000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 UNIT', 'Pemeliharaan genset merupakan kegiatan untuk menjaga dan memastikan genset selalu dalam kondisi siap pakai, andal, dan aman sebagai sumber listrik cadangan guna mendukung kelangsungan operasional perkantoran dan kegiatan pelayanan, khususnya saat terjadi gangguan pasokan listrik utama. Ruang lingkup pekerjaan meliputi pemeliharaan rutin, pemeliharaan berkala, pengujian fungsi, serta perbaikan ringan genset sesuai dengan standar teknis dan ketentuan yang berlaku', '1. Pemeliharaan Rutin Pemeliharaan yang dilakukan secara berkala untuk menjaga kondisi operasional genset, meliputi: - Pemeriksaan level dan kualitas oli mesin - Pemeriksaan air radiator/coolant - Pemeriksaan bahan bakar dan kebocoran - Pemeriksaan sistem kelistrikan dan panel kontrol - Pemeriksaan aki (baterai starter) - Pembersihan area genset dan ruang genset 2. Pemeliharaan Berkala - Pemeliharaan sesuai jam operasi atau jadwal pabrikan, meliputi: - Penggantian oli mesin dan filter oli - Penggantian filter bahan bakar dan filter udara - Penyetelan dan pengecekan sistem pembakaran - Pemeriksaan sistem pendingin dan pelumasan - Pemeriksaan alternator dan sistem pengisian 3. Pengujian dan Operasional - Pengujian start–stop genset secara berkala - Pengujian genset berbeban (load test) - Pemeriksaan kestabilan tegangan dan frekuensi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265690);
