INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148567', 62148567, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan Gedung Tidak Bertingkat', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 74175000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', '1. Pemeliharaan Struktur Bangunan - Pemeriksaan dan perbaikan retak dinding, lantai, dan pondasi ringan - Perbaikan plesteran dan acian dinding - Perawatan lantai (keramik, tegel, beton) - Pengecekan dan perbaikan atap, rangka atap, dan talang air 2. Pemeliharaan Arsitektural - Pengecatan ulang dinding interior dan eksterior - Perbaikan pintu, jendela, kusen, engsel, dan kunci - Perawatan plafon (gypsum, triplek, GRC) - Perbaikan kaca, ventilasi, dan elemen finishing lainnya 3. Pemeliharaan Mekanikal dan Elektrikal (ME) - Pemeriksaan dan perbaikan instalasi listrik (lampu, saklar, stop kontak) - Penggantian armatur lampu dan kabel rusak - Perawatan sistem air bersih dan air kotor - Perbaikan kran, pipa bocor, dan saluran pembuangan 4. Pemeliharaan Lingkungan Bangunan - Pembersihan saluran air dan drainase - Perawatan halaman dan area sekitar bangunan - Perbaikan pagar dan akses masuk gedung 5. Keselamatan dan Keamanan Bangunan - Pemeriksaan kondisi bangunan secara berkala - Penanganan kerusakan ringan yang berpotensi membahayakan - Penerapan prosedur K3 (Keselamatan dan Kesehatan Kerja) sederhana', '1. Persyaratan Umum - Bangunan: Gedung tidak bertingkat (1 lantai) - Kondisi pekerjaan: Pemeliharaan rutin dan perbaikan ringan–sedang - Sistem kerja: Harian / borongan / kontrak sesuai kebutuhan 2. Tenaga Kerja - Tukang bangunan berpengalaman - Teknisi listrik dan plumbing dasar - Mandor/pengawas lapangan (bila diperlukan) 3. Material - Cat interior dan eksterior standar SNI - Semen, pasir, dan bahan bangunan sesuai spesifikasi teknis - Perlengkapan listrik berstandar SNI - Pipa air PVC atau setara 4. Peralatan - Alat tukang manual dan listrik - Alat keselamatan kerja (helm, sarung tangan, sepatu kerja) - Tangga kerja dan peralatan pendukung 5. Standar Pelaksanaan - Mengacu pada standar teknis bangunan gedung yang berlaku - Hasil pekerjaan rapi, kuat, dan aman - Tidak mengganggu aktivitas pengguna gedung - Area kerja dibersihkan setelah pekerjaan selesai', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265721);
