INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148564', 62148564, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Jasa Layanan Hygienis (pengharum ruangan, pest control, rayap)', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Selatan, Makassar (Kota)', 139992000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 THN', 'Penyedia jasa bertanggung jawab melaksanakan layanan hygienis untuk menjaga kebersihan, kenyamanan, dan kesehatan lingkungan kantor/asrama/kelas, dengan ruang lingkup pekerjaan sebagai berikut: 1. Pengharum Ruangan - Menyediakan pengharum ruangan otomatis atau manual di area kantor/asrama/kelas. - Menjamin aroma wangi stabil dan tidak mengganggu aktivitas. - Melakukan pengisian ulang sesuai jadwal. 2. Pest Control - Melakukan pengendalian hama seperti semut, tikus, kecoa, nyamuk, dan serangga lainnya. - Menggunakan pestisida yang aman bagi manusia dan hewan peliharaan. - Menyusun jadwal penyemprotan rutin dan inspeksi hama. 3. Pengendalian Rayap - Melakukan pemeriksaan area rawan rayap. - Melakukan tindakan pencegahan dan pengendalian rayap menggunakan bahan kimia yang aman dan sesuai standar. - Memberikan laporan hasil inspeksi dan tindakan. 4. Monitoring dan Pelaporan - Memeriksa kondisi lingkungan secara rutin. - Menyusun laporan kegiatan dan hasil pengendalian setiap bulan. 5. Keamanan dan Keselamatan - Menjamin semua kegiatan dilakukan sesuai standar K3 dan aman bagi pegawai dan pengunjung. - Menggunakan alat pelindung diri (APD) saat melakukan penyemprotan atau pengendalian hama.', '1. Pengharum Ruangan - Jenis: Spray otomatis, diffuser elektrik, atau aerosol - Area jangkauan: 30–50 m² per unit (disesuaikan ruangan) - Frekuensi penggantian/isi ulang: sesuai kebutuhan 2. Pest Control - Target hama: Serangga (kecoa, semut, lalat), tikus, nyamuk - Metode: Penyemprotan aman, Perangkap (traps) jika diperlukan - Frekuensi: Minimal 1 kali per bulan, inspeksi tambahan sesuai kebutuhan - Bahan: Pestisida ramah lingkungan, aman untuk manusia 3. Pengendalian Rayap - Metode: Pemberian umpan rayap, Penyemprotan atau pengaplikasian gel kimia khusus rayap - Area: Area kayu, perabot, lantai, dinding rawan rayap - Frekuensi: Minimal 1 kali per 6 bulan, inspeksi tambahan bila diperlukan - Bahan: Aman bagi manusia, mengikuti standar SNI atau regulasi lokal 4. Tenaga Pelaksana - Memiliki sertifikasi atau pengalaman di bidang pengendalian hama - Menggunakan APD saat melakukan pekerjaan - Mengikuti protokol keselamatan dan kesehatan kerja 5. Waktu Pelaksanaan - Jadwal rutin bulanan atau sesuai kebutuhan - Pekerjaan dapat dilakukan di luar jam kerja untuk mengurangi gangguan aktivitas Ketentuan Tambahan - Harga sudah termasuk jasa tenaga kerja, bahan, dan peralatan - Penyedia wajib mengganti jika layanan tidak sesuai spesifikasi - Laporan kegiatan wajib diserahkan setiap bulan - Semua bahan dan metode harus ramah lingkungan dan aman untuk pengguna ruangan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265753);
