INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148593', 62148593, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan Scanner', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 1241000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '2 UNIT', 'Pemeliharaan scanner merupakan kegiatan untuk menjaga dan memastikan perangkat scanner selalu dalam kondisi berfungsi optimal, akurat, dan andal guna mendukung kegiatan administrasi, pengarsipan dokumen, serta operasional perkantoran. Ruang lingkup pekerjaan meliputi pemeliharaan rutin, pemeriksaan fungsi, perbaikan ringan, serta penggantian komponen habis pakai sesuai dengan standar teknis pabrikan', '1. Pemeliharaan Rutin Pemeliharaan yang dilakukan secara berkala untuk menjaga kinerja scanner, meliputi: - Pembersihan kaca scanner, roller, dan bagian dalam dari debu dan kotoran - Pemeriksaan kondisi kabel daya dan kabel data - Pemeriksaan kondisi fisik perangkat - Kalibrasi dasar untuk menjaga akurasi hasil scan 2. Pemeriksaan dan Pengujian Fungsi - Pengujian fungsi scan (warna, hitam-putih, dan resolusi) - Pemeriksaan kecepatan dan kualitas hasil pemindaian - Pengujian konektivitas (USB, LAN, atau Wi-Fi sesuai spesifikasi perangkat) - Pemeriksaan kompatibilitas dengan perangkat lunak/aplikasi pendukung 3. Pemeliharaan Berkala - Update atau instalasi ulang driver dan firmware (jika diperlukan) - Penyetelan mekanisme penarik kertas (ADF) - Pemeriksaan sensor dan komponen optik 4. Perbaikan Ringan - Perbaikan terhadap gangguan ringan, antara lain: - Penggantian roller, belt, atau komponen habis pakai - Perbaikan koneksi kabel dan port - Penanganan paper jam - Penyetelan ulang sistem mekanik 5. Standar Pelaksanaan - Pemeliharaan dilakukan oleh teknisi yang kompeten - Menggunakan suku cadang asli atau setara standar pabrikan - Pekerjaan dilakukan sesuai SOP dan manual pabrikan - Menjaga keamanan data dan dokumen selama proses pemeliharaan 6. Pelaporan - Setiap kegiatan pemeliharaan dicatat dalam log pemeliharaan perangkat - Laporan pemeliharaan disampaikan secara berkala kepada pengelola sarana prasarana', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265771);
