INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62150428', 62150428, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN NEGERI PAINAN 01', 'Langganan Internet PN Painan', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Barat, Pesisir Selatan (Kab.)', 174000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 bulan', 'Pengadaan Layanan Koneksi Internet Pengadilan Negeri Painan', 'i. Pemasangan pemrograman dan pengujian koneksi internet sehingga sistem dapat beroperasi dengan baik dan benar. ii. Pemasangan unit-unit pendukung koneksi jaringan internet seperti tertera pada gambar rencana. iii. Pemasangan jaringan koneksi internet dilakukan sampai ke ruang control/operator. iv. Pengaktivasian terhadap layanan koneksi internet v. Menyelenggarakan pemeriksaan dan pengujian terhadap koneksi jaringan internet vi. Mengadakan testing dan commissioning terhadap jaringan koneksi internet dan seluruh peralatan yang terpasang untuk memastikan kualitas link koneksi dan besaran bandwidth vii. Membuat berita acara pelaksanaan kegiatan instalasi aktivasi, testing dan commissioning terhadap layanan koneksi jaringan internet. viii. Memenuhi Service Level Agreement (SLA) terhadap layanan koneksi jaringan internet yang diberikan. ix. Membuat laporan performansi dan monitoring layanan koneksi jaringan internet yang diberikan setiap bulannya. x. Mengadakan training bagi personal yang akan menggunakan/mengoperasikan jaringan koneksi internet ini.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265774);
