INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148588', 62148588, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Alat dan Bahan Pemeliharaan Gedung', 'Barang', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 36202000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PT', 'Pekerjaan Pemeliharaan Gedung merupakan kegiatan untuk menjaga dan mempertahankan kondisi bangunan agar tetap berfungsi dengan baik, aman, dan nyaman digunakan. Pekerjaan ini meliputi pengadaan serta pemasangan alat dan bahan pemeliharaan gedung yang mengalami kerusakan atau penurunan fungsi, dengan ruang lingkup sebagai berikut: - Penggantian dan perbaikan instalasi listrik (lampu, kabel, saklar, stop kontak). - Penggantian dan perbaikan instalasi air bersih dan sanitasi (kran air, pipa, fitting). - Penggantian komponen bangunan pendukung yang rusak atau tidak layak pakai. - Pemeriksaan dan pengujian fungsi instalasi setelah pekerjaan selesai. - Pembersihan area kerja dan pengamanan sisa material.', 'Bahan Pemeliharaan Gedung : a. Kran Air b. Lampu Penerangan c. Kabel Listrik d. Saklar dan Stop Kontak e. Pipa Air f. Bahan Pendukung, seperti Lem PVC, Isolasi listrik, Fitting pipa (elbow, socket, tee), Sekrup dan fisher, Cable ties dll Ketentuan : - Seluruh bahan harus dalam kondisi baru dan layak pakai. - Pekerjaan dilaksanakan sesuai standar keselamatan kerja. - Pemasangan dilakukan oleh tenaga yang kompeten. - Hasil pekerjaan harus berfungsi dengan baik dan rapi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265793);
