INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148574', 62148574, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan Drone', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 4505000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 UNIT', 'Pemeliharaan drone untuk memastikan kelaikan terbang, keselamatan operasional, dan performa perangkat, dengan ruang lingkup pekerjaan sebagai berikut: 1. Pemeriksaan Awal - Melakukan inspeksi kondisi fisik drone sebelum pemeliharaan. - Mengidentifikasi kerusakan, keausan, atau penurunan performa. 2. Pembersihan Perangkat - Membersihkan body, motor, propeller, dan sensor dari debu, pasir, atau kotoran. - Menggunakan alat dan cairan pembersih khusus perangkat elektronik presisi. 3. Pemeriksaan dan Penyetelan Sistem - Memeriksa sistem navigasi, kalibrasi kompas, IMU, dan GPS. - Melakukan kalibrasi ulang jika diperlukan. 4. Pemeriksaan Komponen - Memeriksa kondisi: Motor dan baling-baling (propeller) Baterai dan konektor Kamera dan gimbal Sensor obstacle Remote controller - Mengganti komponen ringan yang rusak atau aus (jika termasuk dalam lingkup pekerjaan). 5. Pemeriksaan Perangkat Lunak - Memeriksa firmware drone dan controller. - Melakukan pembaruan firmware sesuai rekomendasi pabrikan (jika diizinkan). 6. Pengujian Terbang (Test Flight) - Melakukan uji terbang di area aman. - Memastikan stabilitas, respon kontrol, dan kualitas kamera berfungsi normal. 7. Pelaporan - Menyusun laporan hasil pemeliharaan. - Memberikan rekomendasi perbaikan lanjutan atau penggantian suku cadang.', '1. Jenis Drone Drone kamera/fotogrametri 2. Frekuensi Pemeliharaan Insidental (setelah pemakaian intensif atau insiden) 3. Standar Pelaksanaan - Mengacu pada petunjuk teknis pabrikan drone. - Mematuhi prosedur keselamatan penerbangan drone. 4. Tenaga Teknis - Teknisi drone berpengalaman. - Memahami sistem mekanik, elektronik, dan software drone. - Diutamakan memiliki sertifikasi/operator drone (jika diperlukan). 5. Peralatan dan Bahan - Toolkit drone (obeng presisi, multimeter) - Alat kalibrasi - Cairan pembersih elektronik - Software resmi pabrikan 6. Uji terbang: ± 15–30 menit Ketentuan Tambahan - Pemeliharaan tidak termasuk penggantian komponen utama kecuali disepakati. - Penyedia wajib menjaga keamanan dan keselamatan perangkat. - Penyedia bertanggung jawab atas kerusakan akibat kelalaian pekerjaan. - Harga sudah termasuk jasa teknisi dan alat kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265849);
