INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148590', 62148590, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan Printer', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 5865000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 UNIT', 'Pengadaan printer bertujuan untuk menyediakan perangkat cetak dokumen yang andal, efisien, dan sesuai kebutuhan operasional kantor, baik untuk mencetak dokumen hitam-putih maupun berwarna. Ruang lingkup pekerjaan meliputi penyediaan printer baru beserta aksesoris standar, instalasi, uji fungsi, dan dokumentasi serah terima sesuai spesifikasi teknis yang ditentukan', '1. Spesifikasi Umum - Tipe printer: Laser / Inkjet (sesuai kebutuhan kantor) - Fungsi: Cetak dokumen hitam-putih dan/atau warna, minimal 1 fungsi standar (Print / Scan / Copy / Fax jika multifungsi) - Konektivitas: USB, LAN, dan/atau Wi-Fi - Kompatibilitas: Mendukung sistem operasi Windows dan/atau macOS - Kecepatan cetak: Minimal 20-30 lembar per menit (hitam-putih) - Resolusi cetak: Minimal 600 x 600 dpi untuk hitam-putih dan warna 2. Spesifikasi Teknis Tambahan - Kapasitas tray kertas: Minimal 150 lembar - Dukungan ukuran kertas: A4, Letter, Legal - Memiliki fitur duplex (cetak bolak-balik otomatis) jika memungkinkan - Konsumsi daya sesuai standar efisiensi energi (energy saving) 3. Layanan dan Instalasi - Penyediaan kabel data dan adaptor daya sesuai kebutuhan - Instalasi printer dan driver pada komputer pengguna - Uji coba printer untuk memastikan fungsi cetak, scan, dan konektivitas berjalan baik', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 265904);
