INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62186767', 62186767, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Survey Kelaikan Bangunan - SPL 3 - SAPS 3 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Senior Assistant Professional Staff wajib melaksanakan dan menyelesaikan pekerjaan sebagai berikut: a. Melakukan pemeriksaan bidang sipil kepada bangunan yang dilakukan survei. b. Membuat rencana jadwal inspeksi dan surat pemberitahuan inspeksi bangunan gedung. c. Melakukan inspeksi bangunan gedung dalam kelaikan bangunan. d. Mengolah data, monitoring data dan mengarsipkan data hasil inspeksi. e. Membuat laporan pelaksanaan hasil kegiatan survei kelaikan bangunan f. Membuat laporan bulanan dan laporan akhir kegiatan sesuai jadwal yang sudah ditentukan "', '"Spesifikasi Senior Assistant Professional Staff di Bidang Sipil meliputi: • Pendidikan minimal Sarjana S1/D4 Teknik Sipil dari Universitas Negeri/Swasta; • Memiliki KTP dan NPWP; • Mampu bekerja individual dan kelompok/tim; • Bersedia bekerja survei lapangan maupun kantor; • Diutamakan memiliki SIM A /C (opsional); • Diutamakan memiliki kendaraan pribadi roda dua; • Memiliki dan bersedia membawa peralatan kerja yang dibutuhkan (laptop) untuk menunjang pekerjaan; • Bersedia ditempatkan di wilayah Kota Administrasi Jakarta Pusat."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 265932);
