INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148597', 62148597, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan dan Operasional Kendaraan Roda 4', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 156272000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '5 UNIT', '1. Melaksanakan pemeliharaan rutin kendaraan roda 4 agar selalu dalam kondisi laik jalan, aman, dan siap operasional. 2. Melaksanakan pemeliharaan berkala 3. Melakukan perbaikan ringan hingga sedang terhadap komponen kendaraan apabila terjadi kerusakan. 4. Menyediakan kebutuhan operasional kendaraan untuk mendukung kegiatan kedinasan dan pelayanan perkantoran. 5. Melakukan pengecekan harian kendaraan sebelum dan sesudah digunakan. 6. Menjaga kebersihan kendaraan (interior dan eksterior).', 'Spesifikasi Pekerjaan 1. Pemeliharaan Rutin Pemeliharaan yang dilakukan secara berkala untuk menjaga performa kendaraan, meliputi: - Pemeriksaan dan penggantian oli mesin - Pemeriksaan air radiator, minyak rem, dan minyak power steering - Pemeriksaan kondisi ban dan tekanan angin - Pemeriksaan sistem kelistrikan (lampu, klakson, aki) - Pembersihan kendaraan (interior dan eksterior) 2. Pemeliharaan Berkala Pemeliharaan sesuai dengan jadwal servis pabrikan atau jarak tempuh, meliputi: - Tune up mesin - Penggantian filter oli, filter udara, dan filter bahan bakar - Pemeriksaan sistem rem, suspensi, dan kemudi - Pemeriksaan sistem pendingin dan transmisi 3. Perbaikan Ringan Perbaikan terhadap kerusakan ringan yang tidak memerlukan penggantian komponen utama, antara lain: - Penggantian kampas rem - Penggantian aki - Penggantian lampu dan sekring - Perbaikan kecil pada sistem kelistrikan dan mekanikal 4. Operasional Kendaraan - Kegiatan yang mendukung penggunaan kendaraan sehari-hari, meliputi: - Penyediaan bahan bakar minyak (BBM) - Biaya parkir dan tol (jika diperlukan) - Penggantian suku cadang habis pakai - Dukungan penggunaan kendaraan untuk kegiatan dinas 5. Standar Pelaksanaan Pemeliharaan dilakukan di bengkel resmi atau bengkel yang direkomendasikan - Suku cadang yang digunakan harus asli atau setara standar pabrikan - Pelaksanaan pekerjaan sesuai dengan ketentuan keselamatan dan peraturan yang berlaku 6. Pelaporan - Setiap kegiatan pemeliharaan dan operasional dicatat dalam buku kendaraan - Laporan pemeliharaan disampaikan secara berkala kepada pengelola kendaraan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 266052);
