INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148594', 62148594, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan dan Operasional Kendaraan Roda 2', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 16694000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4 UNIT', 'Pemeliharaan kendaraan dinas roda dua merupakan kegiatan untuk menjaga dan memastikan kendaraan selalu dalam kondisi layak jalan, aman, dan siap operasional guna mendukung kelancaran pelaksanaan tugas kedinasan dan operasional perkantoran', '1. Pemeliharaan Rutin - Pemeliharaan yang dilakukan secara berkala untuk menjaga performa kendaraan, meliputi: - Pemeriksaan dan penggantian oli mesin - Pemeriksaan sistem bahan bakar dan pelumasan - Pemeriksaan tekanan dan kondisi ban - Pemeriksaan sistem rem depan dan belakang - Pemeriksaan sistem kelistrikan (lampu, klakson, sein) - Pembersihan kendaraan 2. Pemeliharaan Berkala - Pemeliharaan sesuai jadwal servis pabrikan atau jarak tempuh, meliputi: - Tune up mesin - Penggantian filter udara dan busi - Pemeriksaan dan penyetelan rantai atau CVT - Pemeriksaan suspensi dan kemudi - Pemeriksaan sistem pendinginan (jika berpendingin cairan) 3. Perbaikan Ringan - Perbaikan terhadap kerusakan ringan, antara lain: - Penggantian kampas rem - Penggantian aki - Penggantian lampu dan sekring - Penggantian ban jika diperlukan - Perbaikan minor sistem kelistrikan dan mekanikal 4. Standar Pelaksanaan - Pemeliharaan dilakukan di bengkel resmi atau bengkel yang direkomendasikan - Menggunakan suku cadang asli atau setara standar pabrikan - Pelaksanaan pekerjaan sesuai ketentuan keselamatan dan peraturan yang berlaku 5. Pelaporan - Setiap kegiatan pemeliharaan dicatat dalam buku kendaraan - Laporan pemeliharaan disampaikan secara berkala kepada pengelola kendaraan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 266296);
