INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148572', 62148572, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Biaya Laundry Peralatan Kantor dan Asrama', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 73483000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 BLN', 'Penyedia jasa bertanggung jawab melaksanakan jasa laundry peralatan asrama dan kantor guna menjaga kebersihan, kerapian, dan kenyamanan lingkungan kerja dan hunian, dengan ruang lingkup pekerjaan sebagai berikut: 1. Pengambilan dan Pencatatan - Petugas asrama dan kantor mengumpulkan dan mencatat barang yang mau di-laundry (jumlah dan jenis) - Penyedia Mengambil peralatan dan perlengkapan yang akan dilaundry dari asrama dan kantor sesuai jadwal. 2. Proses Pencucian - Melakukan pencucian sesuai standar kebersihan dan jenis bahan. - Memisahkan pencucian berdasarkan jenis kain (putih, berwarna, tebal, tipis). - Menggunakan deterjen dan bahan pencuci yang aman serta tidak merusak bahan. 3. Pengeringan - Mengeringkan perlengkapan hingga bersih, kering sempurna, dan tidak berbau. - Menggunakan mesin pengering atau penjemuran yang higienis. 4. Penyetrikaan - Menyetrika perlengkapan tertentu sesuai kebutuhan (contoh: sprei, sarung bantal, taplak). 5. Pengemasan - Mengemas hasil laundry secara rapi dan bersih. - Memberi pemisahan dan penandaan sesuai jenis dan lokasi (asrama/kantor). 6. Pengantaran - Mengantarkan hasil laundry ke lokasi asrama dan kantor tepat waktu sesuai jadwal. - Menjamin barang diterima dalam kondisi bersih dan rapi. 7. Pengendalian Mutu dan Tanggung Jawab - Menjamin kualitas kebersihan dan keutuhan barang. - Bertanggung jawab atas kehilangan atau kerusakan akibat kelalaian penyedia jasa.', '1. Jenis Peralatan dan Perlengkapan - Seprai dan sarung bantal - Selimut - Bed cover - Handuk - Gorden - Taplak meja - Peralatan shalat - Perlengkapan kain lainnya milik asrama dan kantor 2. Jenis Layanan - Cuci - Kering - Setrika (sesuai kebutuhan) - Lipat / kemas 3. Frekuensi dan Volume Disesuaikan dengan kebutuhan asrama dan kantor (perkiraan kg/bulan) 4. Standar Kebersihan - Bebas noda, bau, dan kuman. - Tidak merusak warna dan serat kain. - Menggunakan bahan pencuci yang aman bagi kulit dan lingkungan. 5. Waktu Penyelesaian - Waktu proses: Maksimal 5 hari kerja sejak pengambilan - Atau layanan khusus sesuai kesepakatan 6. Peralatan dan Bahan Laundry - Mesin cuci dan pengering berkapasitas memadai. - Setrika uap/listrik. - Deterjen, pewangi, dan disinfektan berkualitas. 7. Tenaga Kerja - Petugas laundry berpengalaman. - Menjaga kebersihan dan standar higiene kerja. 8. Jangka Waktu Pelaksanaan 12 Bulan atau sesuai kesepakatan 9. Pembayaran - Pembayaran sesuai tagihan Ketentuan Tambahan Penyedia wajib menjaga keamanan dan keutuhan barang. Penyedia wajib mengganti barang yang rusak atau hilang. Harga sudah termasuk pengambilan dan pengantaran. Mengutamakan kebersihan, ketepatan waktu, dan kualitas layanan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 266301);
