INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148592', 62148592, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan Laptop', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 18615000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '30, UNIT', 'Pemeliharaan laptop kantor merupakan kegiatan untuk menjaga dan memastikan perangkat laptop selalu dalam kondisi berfungsi optimal, aman, dan andal guna mendukung pelaksanaan tugas administrasi, pelayanan, serta operasional perkantoran.', '1. Pemeliharaan Rutin - Pemeliharaan yang dilakukan secara berkala untuk menjaga kinerja laptop, meliputi: - Pembersihan perangkat (keyboard, layar, port, dan ventilasi) - Pemeriksaan kondisi fisik laptop dan adaptor daya - Pemeriksaan baterai dan sistem pengisian daya - Pemeriksaan fungsi dasar (keyboard, touchpad, kamera, speaker) 2. Pemeriksaan dan Pengujian Fungsi - Pengujian sistem operasi dan aplikasi perkantoran - Pemeriksaan performa perangkat (booting, respons aplikasi) - Pemeriksaan konektivitas (Wi-Fi, LAN, Bluetooth, USB) - Pengujian perangkat pendukung (printer, scanner, proyektor) 3. Pemeliharaan Perangkat Lunak - Update sistem operasi dan aplikasi resmi - Instalasi ulang sistem operasi (jika diperlukan) - Pembersihan file sementara dan pengaturan penyimpanan - Pemeriksaan dan pembaruan antivirus/keamanan 4. Perbaikan Ringan - Perbaikan terhadap gangguan atau kerusakan ringan, antara lain: - Penggantian baterai atau adaptor daya - Perbaikan keyboard atau touchpad - Perbaikan port USB, HDMI, atau LAN - Penanganan laptop lambat, hang, atau error ringan 5. Standar Pelaksanaan - Pemeliharaan dilakukan oleh teknisi yang kompeten - Menggunakan suku cadang asli atau setara standar pabrikan - Menjaga keamanan dan kerahasiaan data pengguna - Pekerjaan dilakukan sesuai SOP dan kebijakan TI instansi 6. Pelaporan - Setiap kegiatan pemeliharaan dicatat dalam log pemeliharaan perangkat - Laporan pemeliharaan disampaikan secara berkala kepada pengelola TI', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 266343);
