INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148571', 62148571, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan LCD/Projector', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 3102000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '5 UNIT', 'Pemeliharaan LCD/Proyektor untuk menjaga kinerja, kualitas tampilan, dan umur pakai peralatan, dengan ruang lingkup pekerjaan sebagai berikut: 1. Pemeriksaan Awal - Melakukan pengecekan kondisi fisik dan fungsi LCD/Proyektor. - Mengidentifikasi kerusakan, penurunan kualitas gambar, atau gangguan fungsi. 2. Pembersihan Perangkat - Membersihkan lensa, filter udara, body, dan port koneksi dari debu dan kotoran. - Menggunakan cairan dan alat pembersih khusus perangkat elektronik. 3. Pemeriksaan dan Penyetelan - Memeriksa fokus, ketajaman, warna, dan pencahayaan tampilan. - Melakukan penyetelan (setting) agar tampilan optimal. 4. Pemeriksaan Komponen - Memeriksa kondisi: Lampu proyektor Kipas pendingin Filter Kabel power dan HDMI/VGA Remote control - Mengganti komponen ringan yang rusak (jika termasuk dalam lingkup pekerjaan). 5. Pengujian Fungsi - Menguji LCD/Proyektor setelah pemeliharaan. - Memastikan perangkat berfungsi normal dan siap digunakan. 6. Pelaporan - Menyusun laporan hasil pemeliharaan. - Memberikan rekomendasi perbaikan lanjutan atau penggantian komponen bila diperlukan.', '1. Jenis Perangkat - LCD Proyektor - Proyektor DLP / LED - Proyektor short throw / standar 2. Frekuensi Pemeliharaan - Berkala (bulanan/triwulanan) - Insidental (sesuai kebutuhan) 3. Standar Pelaksanaan - Mengacu pada petunjuk teknis pabrikan. - Menggunakan peralatan kerja yang aman dan sesuai standar elektronik. 4. Tenaga Teknis - Teknisi berpengalaman minimal 1–2 tahun. - Memahami sistem kerja LCD/Proyektor. - Menerapkan standar keselamatan kerja. 5. Peralatan dan Bahan - Alat pembersih lensa - Blower/air duster - Cairan pembersih khusus elektronik - Obeng dan alat teknis lainnya Ketentuan Tambahan - Pemeliharaan tidak termasuk penggantian lampu utama kecuali disepakati. - Penyedia wajib menjaga keamanan dan kebersihan peralatan. - Penyedia bertanggung jawab atas kerusakan akibat kelalaian pekerjaan. - Harga sudah termasuk jasa teknisi dan alat kerja, dan pajak', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 266399);
