INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148583', 62148583, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan Mesin Air', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 14535000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '3 UNIT', 'Pemeliharaan mesin air (pompa air) untuk memastikan ketersediaan dan kelancaran distribusi air bersih, dengan ruang lingkup pekerjaan sebagai berikut: 1. Pemeriksaan Awal - Melakukan pengecekan kondisi mesin air sebelum pemeliharaan. - Mengidentifikasi kerusakan atau penurunan kinerja mesin. 2. Perawatan Rutin - Membersihkan mesin air dari debu, kotoran, dan endapan. - Melakukan pelumasan pada bagian yang bergerak sesuai standar pabrikan. 3. Pengecekan dan Penyetelan - Memeriksa tekanan air dan kinerja pompa. - Menyetel kembali komponen agar mesin bekerja optimal. 4. Pemeriksaan Komponen a. Memeriksa kondisi: - Motor pompa - Impeller - Seal dan bearing - Saklar otomatis (pressure switch/pelampung) - Instalasi listrik dan kabel b. Mengganti komponen kecil yang rusak (jika termasuk dalam kontrak). 5. Perbaikan Ringan - Melakukan perbaikan ringan untuk kerusakan non-struktural. - Mengatasi kebocoran kecil pada sambungan pipa. 6. Perbaikan pipa saluran air 7. Pengujian - Menguji fungsi mesin air setelah pemeliharaan. - Memastikan aliran dan tekanan air normal. 8. Pelaporan - Membuat laporan hasil pemeliharaan. - Memberikan rekomendasi perbaikan lanjutan jika diperlukan.', '1. Jenis Mesin Jenis: Pompa sumur dalam Pompa booster 2. Frekuensi Pemeliharaan - Harian, bulanan dan insidental - Disesuaikan dengan tingkat pemakaian mesin. 3. Standar Pelaksanaan - Mengacu pada petunjuk teknis pabrikan mesin air. - Mennggunakan peralatan kerja yang sesuai dan aman. 4. Tenaga Teknis - Teknisi berpengalaman minimal 2 tahun. - Memahami sistem pompa dan instalasi air. - Mengutamakan keselamatan kerja. 5. Bahan dan Suku Cadang - Pelumas mesin - Seal, baut, dan komponen kecil lainnya - Suku cadang harus kompatibel dan berkualitas baik (jika termasuk penggantian) - Pipa saluran air 6. Waktu Pelaksanaan Waktu kerja: sesuai kesepakatan Ketentuan Tambahan Penyedia wajib menjaga kebersihan area kerja. Penyedia bertanggung jawab atas kerusakan akibat kelalaian pekerjaan. Harga sudah termasuk jasa teknisi dan peralatan kerja dan pajak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 266479);
