INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148566', 62148566, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'VPS', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 6131000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PT', 'Penyediaan Virtual Private Server (VPS) untuk mendukung kebutuhan hosting, aplikasi, dan pengelolaan data instansi secara aman dan stabil, dengan ruang lingkup pekerjaan sebagai berikut: 1. Penyediaan VPS - Menyediakan VPS sesuai spesifikasi kapasitas dan sistem operasi yang ditentukan. - Menjamin VPS siap digunakan sesuai periode langganan. 2. Instalasi dan Konfigurasi - Melakukan instalasi sistem operasi (Linux/Windows) sesuai kebutuhan. - Konfigurasi layanan VPS termasuk akses SSH/RDP, firewall, dan backup. 3. Pengelolaan dan Pemeliharaan - Memastikan VPS tersedia dan dapat diakses 24/7. - Menyediakan pemeliharaan dasar seperti update sistem dan patch keamanan (jika disepakati). 4. Dukungan Teknis - Menyediakan layanan dukungan teknis (support) selama masa langganan. - Menangani gangguan VPS sesuai SLA yang disepakati. 5. Monitoring dan Laporan - Memberikan laporan status VPS, uptime, penggunaan bandwidth, dan resource server. - Memberikan rekomendasi optimasi bila diperlukan.', '1. Sistem Operasi 2. Spesifikasi Server 3. Ketersediaan Layanan 4. Keamanan 5. Dukungan Teknis dan SLA 6. Periode Langganan 12 bulan (atau disesuaikan kebutuhan) Ketentuan Tambahan - VPS menjadi milik pengguna selama masa langganan - Data dan aplikasi sepenuhnya menjadi tanggung jawab pengguna - Harga sudah termasuk lisensi OS (jika disediakan), resource VPS, dan dukungan teknis - Penyedia wajib menjamin layanan sesuai SLA yang disepakati', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 266701);
