INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148576', 62148576, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Langganan Zoom/Video Conference', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 43116000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 BLN', 'Penyediaan langganan aplikasi Zoom atau platform video conference lain untuk mendukung rapat, pelatihan, dan koordinasi jarak jauh, dengan ruang lingkup pekerjaan sebagai berikut: 1. Penyediaan Layanan Langganan - Menyediakan akun langganan Zoom/Video Conference sesuai jumlah host dan kapasitas peserta. - Menjamin layanan dapat diakses 24/7 selama periode kontrak. 2. Konfigurasi dan Aktivasi - Menyediakan akses akun untuk administrator dan pengguna. - Mengatur konfigurasi dasar seperti meeting, webinar, dan keamanan ruang virtual.', '1. Kapasitas Pengguna - Host: Minimal sesuai kebutuhan (misal 5–10 akun host) - Peserta per meeting: Minimal 100 peserta (atau sesuai kebutuhan instansi) - Webinar (opsional): Kapasitas hingga 500 atau lebih peserta (sesuai paket) 2. Fitur Utama - Video dan audio HD - Screen sharing (desktop, aplikasi, browser) - Rekaman meeting (cloud/ lokal) - Virtual background dan spotlight - Chat selama meeting - Breakout room - Polling dan Q&A (opsional untuk webinar) 3. Sistem Operasi dan Perangkat - Kompatibel dengan: Windows, macOS, Linux; Android dan iOS - Dapat diakses via desktop, laptop, tablet, dan smartphone 4. Keamanan - Enkripsi data meeting - Proteksi ruang meeting: Password, Waiting room, Pengaturan host control - Hak akses admin untuk manajemen akun 5. Ketersediaan Layanan - 24/7 online - Uptime minimal 99% - Support teknis tersedia melalui email, chat, atau telepon 6. Periode Langganan - 12 bulan (atau sesuai kebutuhan) - Termasuk update software dan fitur terbaru selama masa langganan 7. Ketentuan Tambahan - Data meeting dan rekaman menjadi milik pengguna - Harga sudah termasuk lisensi host, support, dan fitur yang tersedia dalam paket - Penghentian layanan mengikuti ketentuan kontrak', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 266762);
