INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62151412', 62151412, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Dokumen Teknis Gedung Pemda - SAPS 6 (MEP) 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Lingkup kegiatan yang dilakukan oleh penyedia jasa Senior Assistant Professional Staff (SAPS) 6 – MEP yang sesuai dengan Lingkup Tugas Suku Dinas Cipta Karya, tata Ruang dan Pertanahan Kota Administrasi Jakarta Pusat meliputi: - Membantu penilaian teknis terhadap gambar, spesifikasi dan rencana anggaran biaya pada bidang Instalasi Arus Kuat dan Instalasi Arus Lemah tahap perencanaan pembangunan yang diajukan oleh Perangkat Daerah pengguna anggaran; - Membantu konsultasi dan evaluasi tahap perencanaan pembangunan bidang Instalasi Arus Kuat dan Instalasi Arus Lemah; - Membantu dalam menyusun bahan persetujuan teknis pada bidang Instalasi Arus Kuat dan Instalasi Arus Lemah tahap perencanaan pembangunan; - Membantu penyusunan Pengembangan Rencana Instalasi Arus Kuat dan Instalasi Arus Lemah, yang dibutuhkan untuk kegiatan perencanaan; - Membantu penyusunan Rencana Detail meliputi gambar - gambar detail Instalasi Arus Kuat dan Instalasi Arus Lemah, yang sesuai dengan desain yang disetujui untuk kegiatan perencanaan; - Membantu melakukan review gambar detail Instalasi Arus Kuat dan Instalasi Arus Lemah terhadap desain perencanaan instalasi; - Membantu menyusun perkiraan biaya (RAB); - Membantu menyusun Rencana Kerja dan Syarat-syarat (RKS); - Membantu menyusun biaya perkiraan pelaksanaan pembangunan gedung (HPS); - Membantu menyusun rincian volume pekerjaan pembangunan gedung (QS); - Melaksanakan Survei lapangan; dan - Membantu dalam pemutakhiran data dan peta. "', '"Senior Assistant Profesional Staff bidang MEP dengan ketentuan sebagai berikut : a. Pendidikan Minimal S1/D4/Setara Jurusan Teknik Elektro/Mesin dari Universitas Negeri/ Swasta dengan status lain yang telah mengikuti ujian negara atau lulusan luar negeri bagi penyedia jasa Senior Assistant Professional Staff; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan yang dibuktikan dengan ijazah dan transkrip nilai pendidikan terakhir Jurusan Teknik Elektro, sertifikat keahlian/teknis seperti AutoCAD, Microsoft Office dan/atau sertifikat pelatihan/kursus; dan c. Pengalaman Kerja minimal 1 tahun di bidang perencanaan, pembangunan, perawatan bangunan gedung dan/atau pekerjaan sejenis. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 267204);
