INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62150596', 62150596, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Dokumen Teknis Gedung Pemda - SAPS 2 (Arsitektur) 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Lingkup kegiatan yang dilakukan oleh penyedia jasa Senior Assistant Professional Staff (SAPS) 2 - Arsitektur, meliputi: - Membantu penilaian teknis terhadap gambar, spesifikasi dan rencana anggaran biaya pada bidang arsitektur tahap perencanaan pembangunan yang diajukan oleh Perangkat Daerah pengguna anggaran; - Membantu konsultasi dan evaluasi perencanaan tahap perencanaan perawatan dan pemeliharaan bidang arsitektur; - Membantu menyusun bahan persetujuan teknis pada bidang arsitektur tahap perencanaan perawatan dan pemeliharaan; - Membantu dalam perencanaan perawatan dan pemeliharaan (Bidang Arsitektur) bangunan gedung pemerintah daerah; - Membantu pembuatan Gambar Kerja Arsitektur bidang gedung pemerintah daerah; - Membantu penyusunan Pengembangan Rencana Arsitektur, yang dibutuhkan untuk kegiatan perencanaan; - Membantu penyusunan Rencana Detail meliputi gambar - gambar detail arsitektur, yang sesuai dengan desain yang disetujui untuk kegiatan perencanaan; - Membantu melakukan review gambar - gambar detail arsitektur terhadap desain yang disetujui untuk kegiatan perencanaan; - Membantu menyusun Rencana Anggaran Biaya (RAB); - Membantu menyusun Rencana Kerja dan Syarat-syarat (RKS); - Membantu menyusun biaya perkiraan perencanaan pelaksanaan pembangunan gedung (HPS); - Membantu menyusun rincian volume pekerjaan perencanaan pembangunan gedung (QS); - Melaksanakan Survei dan pengumpulan data di lapangan; dan - Membantu dalam pemutakhiran data dan peta. "', '"Senior Assistant Profesional Staff bidang Arsitektur dengan ketentuan sebagai berikut : Pendidikan Minimal S1/D4/Setara Jurusan Arsitektur dari Universitas Negeri/ Swasta dengan status lain yang telah mengikuti ujian negara atau lulusan luar negeri bagi penyedia jasa Senior Assistant Professional Staff; Memiliki kompetensi sesuai bidang yang dipersyaratkan yang dibuktikan dengan ijazah dan transkrip nilai pendidikan terakhir Jurusan Arsitektur, sertifikat keahlian/teknis seperti aplikasi Sketch-Up / AutoCAD / Adobe (Photoshop/InDesign/Illustrator) / Lumion/3D Max, Microsoft Office dan/atau sertifikat pelatihan/kursus; dan Pengalaman Kerja minimal 1 tahun di bidang perencanaan, pembangunan, perawatan bangunan gedung dan/atau pekerjaan sejenis."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 267980);
